	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\newcommand{\myRelationPlot}[5]{
		% #1: Set A
		% #2: Indecies of Set A
		% #3: Set B 
		% #4: Indecies of Set B
		% #5: Pairs in the relation
	\begin{axis}[
		clip=false,
		tick label style={font=\footnotesize},
		label style={font=\small},
		tick style={draw=black,thick},
		axis line style = thick,
		axis y line = center, axis x line = middle,
		%axis equal, grid = both,
		xmin = {0}, xmax = {\plotWidth},
		ymin = {0}, ymax = {\plotHeight},
		xtick = {#2}, ytick = {#4},
		xticklabels = {}, yticklabels = {},
		%x tick label style={yshift={(\tick==1)*-0pt},xshift={(\tick==1)*-5pt}},
		xlabel = {$\setAname$}, ylabel = {$\setBname$},
		xlabel style={below right}, ylabel style={above right},
		every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west},
		every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south}
	]

		% Grid
		\foreach \i [count=\xi] in {#1} {
			\edef\temp{
				\noexpand\draw[lightgray, dashed, opacity=0.5] 
					(axis cs:\xi,0) -- (axis cs:\xi,\plotHeight-0.5);
				\noexpand\node[below=2pt] at (axis cs:\xi,0) {$\i$};}
				\temp};
		\foreach \i [count=\xi] in {#3} {
			\edef\temp{
				\noexpand\draw[lightgray, dashed, opacity=0.5] 
					(axis cs:0,\xi) -- (axis cs:\plotWidth-0.5,\xi);
				\noexpand\node[left=2pt] at (axis cs:0,\xi) {$\i$};
				}
			\temp}; 

		% Plot
		\plot[mark options={draw=none, opacity=0, fill opacity=1, fill=\ccolor}, 
			only marks, mark size=\sizeOfdots] coordinates {#5};

	\end{axis}	
	}	

	\begin{tikzpicture}

	\def\ccolor{deepskyblue} % Dot color
	\def\m{3} % Card(A)
	\def\n{3} % Card(B)
	\def\setAname{A} % Set A name
	\def\setBname{B} % Set B name

	\def\sizeOfdots{3pt} % Radius of the dots

	\pgfmathsetmacro{\plotWidth}{\m+1}
	\pgfmathsetmacro{\plotHeight}{\n+1}

	% Draw the plot 	
	\myRelationPlot
		{-2,-1,0} % Set A
		{1,2,3} % Indecies of Set A
		{3,5,7} % Set B
		{1,2,3} % Indecies of Set B
		{(1,3) (3,3) (2,2) (2,1)} % Pairs in the relation (use indexes, no commas between pairs)

	\end{tikzpicture}
\end{document}

