\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}

\begin{document}
\begin{tikzpicture}[
	->, >= latex, shorten >= 1pt, node distance=3cm, thick,
	main node/.style = {circle, draw, minimum size=6mm},
	loop/.style = {looseness=20}
]

	% Nodes
	\node[main node, draw=deepskyblue!80, fill=deepskyblue!20, label=center:{$\bigtriangleup$}] (1) {};
	\node[main node, draw=deepskyblue!80, fill=deepskyblue!20, label=center:{\small$\bigcirc$}] (2) [below left of = 1] {};
	\node[main node, draw=deepskyblue!80, fill=deepskyblue!20, label=center:{\Large$\star$}] (3) [below right of = 1] {};

	% Arrows
	\path
		(1) edge [loop above] (1)
		(1) edge [bend right] (2)
		(2) edge (1)
		%(2) edge [loop below] (2)
		(1) edge (3);
		%(3) edge (2);      

\end{tikzpicture}
\end{document}

